import test from'node:test';import assert from'node:assert/strict';
import{example,availability,updateNode}from'./engine.js';
import{createStudy,saveDesign,designRows,recipe,failureExplanation,validateStudy}from'./study.js';
test('saved designs are immutable snapshots with their assumptions and evidence',()=>{const graph=example(),s=createStudy();s.name='Our proposal';s.assumptions='Same response contract';s.evidence='Check switching';s.effort=5;const saved=saveDesign(s,graph);graph.nodes[0].p=.1;s.assumptions='changed';assert.equal(saved.variants[0].graph.nodes[0].p,.99);assert.equal(saved.variants[0].assumptions,'Same response contract');assert.equal(saved.variants[0].evidence,'Check switching');assert.equal(s.variants.length,0);assert.deepEqual(validateStudy(JSON.parse(JSON.stringify(saved))),saved);});
test('only matching success definitions get a baseline gain',()=>{const g=example(),s=saveDesign(createStudy(),g);assert.ok(Math.abs(designRows(s,g)[0].gain)<1e-12);s.baselineBasis='A different service succeeds.';assert.equal(designRows(s,g)[0].gain,null);});
test('independent clocks remove the original common failure but a channel backup does not',()=>{const base=example(),before=structuredClone(base);const backup=recipe(base,'backup'),separate=recipe(base,'separate');assert.equal(availability(backup.graph,['clock']),0);assert.ok(availability(separate.graph,['clock'])>0);assert.deepEqual(base,before);assert.ok(availability(separate.graph)>availability(base));});
test('local fallback retains its own measurement dependency and shared command channel',()=>{const base=example(),r=recipe(base,'fallback');assert.ok(availability(r.graph,['clock'])>0);assert.equal(availability(r.graph,['command']),0);const data=r.graph.nodes.find(n=>n.label==='Local fallback measurements');assert.equal(availability(r.graph,['clock',data.id]),0);assert.ok(r.assumptions.includes('same promised response'));});
test('failure explanations distinguish an unused component from an upstream requirement',()=>{const g=example();assert.equal(failureExplanation(g,'clock').heldDown,0);assert.ok(failureExplanation(g,'command').upstream.includes('Shared clock'));g.nodes.push({id:'unused',label:'Unused',kind:'component',p:.1,x:0,y:0,inputs:[]});assert.equal(failureExplanation(g,'unused').used,false);assert.ok(failureExplanation(g,'feed-a').heldDown>0);});
test('snapshots are bounded and invalid effort is rejected without changing prior work',()=>{let s=createStudy();for(let i=0;i<8;i++)s=saveDesign(s,example());assert.throws(()=>saveDesign(s,example()),/Eight/);assert.equal(s.variants.length,8);assert.throws(()=>validateStudy({...s,effort:NaN}),/Effort/);assert.throws(()=>saveDesign({...createStudy(),basis:''},example()),/Define/);});
